window.FILESRC={"pkg/ddl/storage_class_interval.go": ["// Copyright 2026 PingCAP, Inc.", "//", "// Licensed under the Apache License, Version 2.0 (the \"License\");", "// you may not use this file except in compliance with the License.", "// You may obtain a copy of the License at", "//", "//     http://www.apache.org/licenses/LICENSE-2.0", "//", "// Unless required by applicable law or agreed to in writing, software", "// distributed under the License is distributed on an \"AS IS\" BASIS,", "// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.", "// See the License for the specific language governing permissions and", "// limitations under the License.", "", "package ddl", "", "import (", "\t\"fmt\"", "\t\"strconv\"", "\t\"strings\"", "\t\"time\"", "", "\t\"github.com/pingcap/failpoint\"", "\t\"github.com/pingcap/tidb/pkg/meta/model\"", "\t\"github.com/pingcap/tidb/pkg/parser\"", "\t\"github.com/pingcap/tidb/pkg/parser/ast\"", "\t\"github.com/pingcap/tidb/pkg/parser/mysql\"", "\t\"github.com/pingcap/tidb/pkg/types\"", "\t\"github.com/pingcap/tidb/pkg/util/dbterror\"", ")", "", "// storageClassIntervalMaxCount bounds <n> so that converting QUARTER and WEEK", "// cannot overflow and the result stays within the range types.AddDate accepts.", "const storageClassIntervalMaxCount = 10000 * 365", "", "// storageClassInterval is a parsed `INTERVAL <n> <unit>` value of 'less_than'.", "type storageClassInterval struct {", "\tcount int64", "\tunit  ast.TimeUnitType", "}", "", "var storageClassIntervalUnits = map[string]ast.TimeUnitType{", "\t\"YEAR\":    ast.TimeUnitYear,", "\t\"QUARTER\": ast.TimeUnitQuarter,", "\t\"MONTH\":   ast.TimeUnitMonth,", "\t\"WEEK\":    ast.TimeUnitWeek,", "\t\"DAY\":     ast.TimeUnitDay,", "}", "", "// parseStorageClassInterval parses a 'less_than' value. isInterval is false", "// when the value is a boundary literal rather than an interval.", "func parseStorageClassInterval(value string) (_ storageClassInterval, isInterval bool, _ error) {", "\tfields := strings.Fields(value)", "\tif len(fields) == 0 || !strings.EqualFold(fields[0], \"INTERVAL\") {", "\t\treturn storageClassInterval{}, false, nil", "\t}", "\tinvalid := dbterror.ErrStorageClassInvalidSpec.GenWithStackByArgs(fmt.Sprintf(", "\t\t\"invalid 'less_than' interval: '%-.64s', expected 'INTERVAL <n> YEAR|QUARTER|MONTH|WEEK|DAY' with a positive integer <n>\", value))", "\tif len(fields) != 3 {", "\t\treturn storageClassInterval{}, true, invalid", "\t}", "\tfor _, c := range fields[1] {", "\t\tif c < '0' || c > '9' {", "\t\t\treturn storageClassInterval{}, true, invalid", "\t\t}", "\t}", "\tcount, err := strconv.ParseInt(fields[1], 10, 64)", "\tif err != nil || count <= 0 || count > storageClassIntervalMaxCount {", "\t\treturn storageClassInterval{}, true, invalid", "\t}", "\tunit, ok := storageClassIntervalUnits[strings.ToUpper(fields[2])]", "\tif !ok {", "\t\treturn storageClassInterval{}, true, invalid", "\t}", "\treturn storageClassInterval{count: count, unit: unit}, true, nil", "}", "", "// cutoff returns now minus the interval in UTC, with MySQL month-end semantics.", "func (i storageClassInterval) cutoff(now time.Time) (time.Time, error) {", "\tvar years, months, days int64", "\tswitch i.unit {", "\tcase ast.TimeUnitYear:", "\t\tyears = i.count", "\tcase ast.TimeUnitQuarter:", "\t\tmonths = 3 * i.count", "\tcase ast.TimeUnitMonth:", "\t\tmonths = i.count", "\tcase ast.TimeUnitWeek:", "\t\tdays = 7 * i.count", "\tdefault:", "\t\tdays = i.count", "\t}", "\tcutoff, err := types.AddDate(-years, -months, -days, now.UTC())", "\tif err != nil || cutoff.Year() < 1 {", "\t\treturn time.Time{}, dbterror.ErrStorageClassInvalidSpec.GenWithStackByArgs(\"'less_than' interval is out of range\")", "\t}", "\treturn cutoff, nil", "}", "", "// storageClassIntervalNow returns the time interval selectors are evaluated at.", "func storageClassIntervalNow() time.Time {", "\tnow := time.Now()", "\tfailpoint.InjectCall(\"mockStorageClassIntervalNow\", &now)", "\treturn now.UTC()", "}", "", "type storageClassIntervalKeyKind int", "", "const (", "\tstorageClassIntervalKeyColumnTime storageClassIntervalKeyKind = iota", "\tstorageClassIntervalKeyToDays", "\tstorageClassIntervalKeyUnixTimestamp", ")", "", "func errStorageClassIntervalUnsupportedPartition() error {", "\treturn dbterror.ErrStorageClassInvalidSpec.GenWithStackByArgs(", "\t\t\"'less_than' interval only supports RANGE COLUMNS(DATE/DATETIME), RANGE(TO_DAYS(col)) or RANGE(UNIX_TIMESTAMP(col)) partitions\")", "}", "", "// getStorageClassIntervalKeyKind returns how a cutoff time maps onto the", "// partition key of tbInfo, or an error if interval selectors are unsupported.", "func getStorageClassIntervalKeyKind(tbInfo *model.TableInfo) (storageClassIntervalKeyKind, error) {", "\tpi := tbInfo.Partition", "\tif pi == nil || pi.Type != ast.PartitionTypeRange {", "\t\treturn 0, errStorageClassIntervalUnsupportedPartition()", "\t}", "\tif len(pi.Columns) > 0 {", "\t\tif len(pi.Columns) != 1 {", "\t\t\treturn 0, errStorageClassIntervalUnsupportedPartition()", "\t\t}", "\t\tcol := findColumnByName(pi.Columns[0].L, tbInfo)", "\t\tif col == nil {", "\t\t\treturn 0, errStorageClassIntervalUnsupportedPartition()", "\t\t}", "\t\tswitch col.GetType() {", "\t\tcase mysql.TypeDate, mysql.TypeDatetime:", "\t\t\treturn storageClassIntervalKeyColumnTime, nil", "\t\t}", "\t\treturn 0, errStorageClassIntervalUnsupportedPartition()", "\t}", "\tstmts, _, err := parser.New().ParseSQL(\"SELECT \" + pi.Expr)", "\tif err != nil || len(stmts) != 1 {", "\t\treturn 0, errStorageClassIntervalUnsupportedPartition()", "\t}", "\tsel, ok := stmts[0].(*ast.SelectStmt)", "\tif !ok || sel.Fields == nil || len(sel.Fields.Fields) != 1 {", "\t\treturn 0, errStorageClassIntervalUnsupportedPartition()", "\t}", "\tfn, ok := sel.Fields.Fields[0].Expr.(*ast.FuncCallExpr)", "\tif !ok || len(fn.Args) != 1 {", "\t\treturn 0, errStorageClassIntervalUnsupportedPartition()", "\t}", "\tif _, ok := fn.Args[0].(*ast.ColumnNameExpr); !ok {", "\t\treturn 0, errStorageClassIntervalUnsupportedPartition()", "\t}", "\tswitch fn.FnName.L {", "\tcase ast.ToDays:", "\t\treturn storageClassIntervalKeyToDays, nil", "\tcase ast.UnixTimestamp:", "\t\treturn storageClassIntervalKeyUnixTimestamp, nil", "\t}", "\treturn 0, errStorageClassIntervalUnsupportedPartition()", "}", "", "// convertStorageClassIntervalToLessThan converts an interval to the 'less_than'", "// literal it stands for at now, in the partition key domain, so partitions are", "// matched exactly as for a literal selector.", "func convertStorageClassIntervalToLessThan(tbInfo *model.TableInfo, interval storageClassInterval, now time.Time) (string, error) {", "\tkind, err := getStorageClassIntervalKeyKind(tbInfo)", "\tif err != nil {", "\t\treturn \"\", err", "\t}", "\tcutoff, err := interval.cutoff(now)", "\tif err != nil {", "\t\treturn \"\", err", "\t}", "\tcutoffTime := types.NewTime(types.FromGoTime(cutoff), mysql.TypeDatetime, types.MaxFsp)", "\tswitch kind {", "\tcase storageClassIntervalKeyToDays:", "\t\t// Same as TO_DAYS(cutoff): a partition matches only if all its dates", "\t\t// are before the cutoff date.", "\t\treturn strconv.FormatInt(types.TimestampDiff(\"DAY\", types.ZeroDate, cutoffTime), 10), nil", "\tcase storageClassIntervalKeyUnixTimestamp:", "\t\treturn strconv.FormatInt(cutoff.Unix(), 10), nil", "\t}", "\treturn cutoffTime.String(), nil", "}", "", "// checkStorageClassIntervalDef validates the rule-level restrictions of an", "// interval selector.", "func checkStorageClassIntervalDef(def *model.StorageClassDef) error {", "\tif def.LessThan == nil {", "\t\treturn nil", "\t}", "\t_, isInterval, err := parseStorageClassInterval(*def.LessThan)", "\tif err != nil || !isInterval {", "\t\treturn err", "\t}", "\tif def.Tier != model.StorageClassTierIA {", "\t\treturn dbterror.ErrStorageClassInvalidSpec.GenWithStackByArgs(\"'less_than' interval only supports tier 'IA'\")", "\t}", "\tif len(def.Transitions) > 0 {", "\t\treturn dbterror.ErrStorageClassInvalidSpec.GenWithStackByArgs(\"can not specify 'less_than' interval and 'transitions' together\")", "\t}", "\treturn nil", "}", "", "// checkStorageClassIntervalPartitionKey rejects an interval selector on a table", "// whose partition key it cannot map a cutoff onto. Only new CREATE/ALTER", "// requests are checked; existing rules keep their behavior when partitions are", "// rebuilt or intervals are recalculated.", "func checkStorageClassIntervalPartitionKey(engineAttribute string, tbInfo *model.TableInfo) error {", "\tif engineAttribute == \"\" || tbInfo == nil {", "\t\treturn nil", "\t}", "\tattr, err := model.ParseEngineAttributeFromString(engineAttribute)", "\tif err != nil {", "\t\treturn dbterror.ErrEngineAttributeInvalidFormat.GenWithStackByArgs(fmt.Sprintf(\"'%v'\", err))", "\t}", "\tif attr.StorageClass == nil {", "\t\treturn nil", "\t}", "\tsettings, err := BuildStorageClassSettingsFromJSON(attr.StorageClass)", "\tif err != nil {", "\t\treturn err", "\t}", "\tfor _, def := range settings.Defs {", "\t\tif def.LessThan == nil {", "\t\t\tcontinue", "\t\t}", "\t\t_, isInterval, err := parseStorageClassInterval(*def.LessThan)", "\t\tif err != nil {", "\t\t\treturn err", "\t\t}", "\t\tif !isInterval {", "\t\t\tcontinue", "\t\t}", "\t\tif _, err := getStorageClassIntervalKeyKind(tbInfo); err != nil {", "\t\t\treturn err", "\t\t}", "\t}", "\treturn nil", "}"], "pkg/ddl/storage_class_interval_recalc.go": ["// Copyright 2026 PingCAP, Inc.", "//", "// Licensed under the Apache License, Version 2.0 (the \"License\");", "// you may not use this file except in compliance with the License.", "// You may obtain a copy of the License at", "//", "//     http://www.apache.org/licenses/LICENSE-2.0", "//", "// Unless required by applicable law or agreed to in writing, software", "// distributed under the License is distributed on an \"AS IS\" BASIS,", "// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.", "// See the License for the specific language governing permissions and", "// limitations under the License.", "", "package ddl", "", "import (", "\t\"context\"", "\t\"fmt\"", "\t\"time\"", "", "\t\"github.com/pingcap/errors\"", "\t\"github.com/pingcap/failpoint\"", "\t\"github.com/pingcap/tidb/pkg/config\"", "\t\"github.com/pingcap/tidb/pkg/ddl/logutil\"", "\tsess \"github.com/pingcap/tidb/pkg/ddl/session\"", "\t\"github.com/pingcap/tidb/pkg/infoschema\"", "\tinfoschemacontext \"github.com/pingcap/tidb/pkg/infoschema/context\"", "\t\"github.com/pingcap/tidb/pkg/meta/model\"", "\t\"github.com/pingcap/tidb/pkg/metrics\"", "\t\"github.com/pingcap/tidb/pkg/sessionctx/vardef\"", "\t\"github.com/pingcap/tidb/pkg/util/sqlescape\"", "\t\"github.com/pingcap/tidb/pkg/util/tracing\"", "\t\"go.uber.org/zap\"", ")", "", "const (", "\t// storageClassIntervalRecalcCheckInterval is how often the owner re-reads", "\t// the recalculation period, so changing it takes effect without waiting", "\t// for the previous period to end.", "\tstorageClassIntervalRecalcCheckInterval = time.Minute", "", "\tstorageClassIntervalRecalcFailedMetric = \"storage_class_interval_recalc_failed\"", ")", "", "// storageClassIntervalChanges are the partition storage class changes that", "// re-evaluating the interval selectors of a table would make.", "type storageClassIntervalChanges struct {", "\thasInterval bool", "\t// toIA are partitions converted from STANDARD to IA.", "\ttoIA []string", "\t// notToIA are partitions converted in any other way. Time only moves", "\t// forward, so these indicate clock skew and are never applied by", "\t// recalculation.", "\tnotToIA []string", "}", "", "func evalStorageClassIntervalChanges(tblInfo *model.TableInfo, now time.Time) (storageClassIntervalChanges, error) {", "\tvar changes storageClassIntervalChanges", "\tif tblInfo.Partition == nil || tblInfo.EngineAttribute == \"\" {", "\t\treturn changes, nil", "\t}", "\tattr, err := model.ParseEngineAttributeFromString(tblInfo.EngineAttribute)", "\tif err != nil {", "\t\treturn changes, errors.Trace(err)", "\t}", "\tif attr.StorageClass == nil {", "\t\treturn changes, nil", "\t}", "\tsettings, err := BuildStorageClassSettingsFromJSON(attr.StorageClass)", "\tif err != nil {", "\t\treturn changes, errors.Trace(err)", "\t}", "\tpartitions := tblInfo.Partition.Definitions", "\tevaluator, err := newStorageClassPartitionEvaluator(tblInfo, partitions, settings, now)", "\tif err != nil {", "\t\treturn changes, errors.Trace(err)", "\t}", "\tchanges.hasInterval = evaluator.hasInterval", "\tif !evaluator.hasInterval {", "\t\treturn changes, nil", "\t}", "\tfor i := range partitions {", "\t\tpart := &partitions[i]", "\t\tdef, err := evaluator.matchingDef(part)", "\t\tif err != nil {", "\t\t\treturn changes, errors.Trace(err)", "\t\t}", "\t\tnewTier := model.StorageClassTierDefault", "\t\tif def != nil {", "\t\t\tnewTier = def.Tier", "\t\t}", "\t\toldTier := normalizedStorageClassTransitionTarget(part.StorageClassTier)", "\t\tnewTier = normalizedStorageClassTransitionTarget(newTier)", "\t\tswitch {", "\t\tcase oldTier == newTier:", "\t\tcase oldTier == model.StorageClassTierStandard && newTier == model.StorageClassTierIA:", "\t\t\tchanges.toIA = append(changes.toIA, part.Name.O)", "\t\tdefault:", "\t\t\tchanges.notToIA = append(changes.notToIA, part.Name.O)", "\t\t}", "\t}", "\treturn changes, nil", "}", "", "// shouldApplyStorageClassIntervalRecalculation reports whether an interval", "// recalculation job should apply, and logs why not: at least one partition", "// changes, and every change is from STANDARD to IA. Anything else means the", "// rule changed or the clock moved backwards, and the job does nothing.", "func shouldApplyStorageClassIntervalRecalculation(tblInfo *model.TableInfo, old, current map[int64]physicalStorageClass) bool {", "\tlogger := logutil.DDLLogger().With(zap.Int64(\"tableID\", tblInfo.ID), zap.String(\"table\", tblInfo.Name.O))", "\tchanged := changedStorageClassPhysicalIDs(old, current)", "\tif len(changed) == 0 {", "\t\tlogger.Info(\"storage class interval recalculation skipped, no partition changes\")", "\t\treturn false", "\t}", "\tfor physicalID := range changed {", "\t\tif normalizedStorageClassTransitionTarget(old[physicalID].tier) != model.StorageClassTierStandard ||", "\t\t\tnormalizedStorageClassTransitionTarget(current[physicalID].tier) != model.StorageClassTierIA {", "\t\t\tlogger.Warn(\"storage class interval recalculation skipped, partitions would leave IA\",", "\t\t\t\tzap.Int64(\"physicalID\", physicalID))", "\t\t\treturn false", "\t\t}", "\t}", "\treturn true", "}", "", "// storageClassIntervalRecalculator periodically re-evaluates interval", "// selectors on the DDL owner and submits ActionModifyEngineAttribute jobs for", "// tables with partitions newly crossing the cutoff.", "type storageClassIntervalRecalculator struct {", "\tinfoCache *infoschema.InfoCache", "\tsessPool  *sess.Pool", "\texecutor  *executor", "}", "", "func (r *storageClassIntervalRecalculator) run(ctx context.Context) {", "\tvar lastRound time.Time", "\ttimer := time.NewTimer(0)", "\tdefer timer.Stop()", "\tfor {", "\t\tselect {", "\t\tcase <-ctx.Done():", "\t\t\treturn", "\t\tcase <-timer.C:", "\t\t}", "\t\tperiod, err := r.loadPeriod(ctx)", "\t\tif err != nil {", "\t\t\tif ctx.Err() != nil {", "\t\t\t\treturn", "\t\t\t}", "\t\t\tlogutil.DDLLogger().Warn(\"load storage class interval recalculation period failed\", zap.Error(err))", "\t\t\tmetrics.DDLCounter.WithLabelValues(storageClassIntervalRecalcFailedMetric).Inc()", "\t\t} else if period > 0 && (lastRound.IsZero() || time.Since(lastRound) >= period) &&", "\t\t\tconfig.GetGlobalConfig().EnableStorageClass {", "\t\t\tlastRound = time.Now()", "\t\t\tr.runRound(ctx)", "\t\t\tfailpoint.InjectCall(\"afterStorageClassIntervalRecalcRound\")", "\t\t}", "\t\tcheckInterval := storageClassIntervalRecalcCheckInterval", "\t\tfailpoint.InjectCall(\"mockStorageClassIntervalRecalcCheckInterval\", &checkInterval)", "\t\ttimer.Reset(checkInterval)", "\t}", "}", "", "func (r *storageClassIntervalRecalculator) loadPeriod(ctx context.Context) (time.Duration, error) {", "\tif r.sessPool == nil {", "\t\treturn 0, errors.New(\"session pool is unavailable\")", "\t}", "\tsctx, err := r.sessPool.Get()", "\tif err != nil {", "\t\treturn 0, errors.Trace(err)", "\t}", "\tdefer r.sessPool.Put(sctx)", "\t//nolint:forbidigo", "\tvalue, err := sctx.GetSessionVars().GlobalVarsAccessor.GetGlobalSysVar(vardef.TiDBStorageClassIntervalRecalcPeriod)", "\tif err != nil {", "\t\treturn 0, errors.Trace(err)", "\t}", "\tperiod, err := time.ParseDuration(value)", "\tif err != nil {", "\t\treturn 0, errors.Trace(err)", "\t}", "\tfailpoint.InjectCall(\"mockStorageClassIntervalRecalcPeriod\", &period)", "\treturn period, ctx.Err()", "}", "", "func (r *storageClassIntervalRecalculator) runRound(ctx context.Context) {", "\tdefer func() {", "\t\tif rec := recover(); rec != nil {", "\t\t\tlogutil.DDLLogger().Warn(\"storage class interval recalculation panicked\",", "\t\t\t\tzap.Any(\"recover\", rec), zap.Stack(\"stack\"))", "\t\t\tmetrics.DDLCounter.WithLabelValues(storageClassIntervalRecalcFailedMetric).Inc()", "\t\t}", "\t}()", "\tis := r.infoCache.GetLatest()", "\tif is == nil {", "\t\tlogutil.DDLLogger().Warn(\"storage class interval recalculation skipped, information schema is unavailable\")", "\t\tmetrics.DDLCounter.WithLabelValues(storageClassIntervalRecalcFailedMetric).Inc()", "\t\treturn", "\t}", "\tnow := storageClassIntervalNow()", "\tvar tables, submitted, failed int", "\tdefer func() {", "\t\tlogutil.DDLLogger().Info(\"storage class interval recalculation round finished\",", "\t\t\tzap.Time(\"now\", now), zap.Int(\"tables\", tables), zap.Int(\"submitted\", submitted), zap.Int(\"failed\", failed))", "\t}()", "\tfor _, schema := range is.ListTablesWithSpecialAttribute(infoschemacontext.PartitionAttribute) {", "\t\tdbInfo, ok := is.SchemaByName(schema.DBName)", "\t\tif !ok {", "\t\t\tcontinue", "\t\t}", "\t\tfor _, tblInfo := range schema.TableInfos {", "\t\t\tif ctx.Err() != nil {", "\t\t\t\treturn", "\t\t\t}", "\t\t\ttables++", "\t\t\tisSubmitted, err := r.recalcTable(ctx, dbInfo, tblInfo, now)", "\t\t\tif isSubmitted {", "\t\t\t\tsubmitted++", "\t\t\t}", "\t\t\tif err != nil && ctx.Err() == nil {", "\t\t\t\tfailed++", "\t\t\t\tlogutil.DDLLogger().Warn(\"storage class interval recalculation failed\",", "\t\t\t\t\tzap.Int64(\"tableID\", tblInfo.ID), zap.String(\"table\", tblInfo.Name.O), zap.Error(err))", "\t\t\t\tmetrics.DDLCounter.WithLabelValues(storageClassIntervalRecalcFailedMetric).Inc()", "\t\t\t}", "\t\t}", "\t}", "}", "", "// recalcTable submits a job if partitions of the table newly cross the cutoff,", "// and reports whether it did.", "func (r *storageClassIntervalRecalculator) recalcTable(", "\tctx context.Context,", "\tdbInfo *model.DBInfo,", "\ttblInfo *model.TableInfo,", "\tnow time.Time,", ") (submitted bool, err error) {", "\tdefer func() {", "\t\tif rec := recover(); rec != nil {", "\t\t\terr = errors.Errorf(\"storage class interval recalculation panicked: %v\", rec)", "\t\t\tlogutil.DDLLogger().Warn(\"storage class interval recalculation panicked\", zap.Stack(\"stack\"))", "\t\t}", "\t}()", "\tchanges, err := evalStorageClassIntervalChanges(tblInfo, now)", "\tif err != nil || !changes.hasInterval {", "\t\treturn false, err", "\t}", "\tif len(changes.notToIA) > 0 {", "\t\treturn false, errors.Errorf(\"partitions %v would leave IA, the clock may have moved backwards\", changes.notToIA)", "\t}", "\tif len(changes.toIA) == 0 {", "\t\treturn false, nil", "\t}", "\tfailpoint.InjectCall(\"beforeStorageClassIntervalRecalcSubmit\", tblInfo.ID)", "\tif err := r.submit(ctx, dbInfo, tblInfo, changes.toIA); err != nil {", "\t\treturn false, err", "\t}", "\treturn true, nil", "}", "", "// submit enqueues the job without waiting for it to finish. A failed or", "// skipped job is retried by the next round, which re-evaluates the table.", "func (r *storageClassIntervalRecalculator) submit(", "\tctx context.Context,", "\tdbInfo *model.DBInfo,", "\ttblInfo *model.TableInfo,", "\ttoIA []string,", ") error {", "\tquery, err := sqlescape.EscapeSQL(\"ALTER TABLE %n.%n ENGINE_ATTRIBUTE = %?\", dbInfo.Name.O, tblInfo.Name.O, tblInfo.EngineAttribute)", "\tif err != nil {", "\t\treturn errors.Trace(err)", "\t}", "\tjob := &model.Job{", "\t\tVersion:    model.GetJobVerInUse(),", "\t\tSchemaID:   dbInfo.ID,", "\t\tTableID:    tblInfo.ID,", "\t\tSchemaName: dbInfo.Name.L,", "\t\tTableName:  tblInfo.Name.L,", "\t\tType:       model.ActionModifyEngineAttribute,", "\t\tBinlogInfo: &model.HistoryInfo{},", "\t\tTraceInfo:  &tracing.TraceInfo{},", "\t\tQuery:      query,", "\t}", "\targs := &model.ModifyTableEngineAttributeArgs{", "\t\tEngineAttribute:       tblInfo.EngineAttribute,", "\t\tIntervalRecalculation: true,", "\t}", "\tjobW := NewJobWrapperWithArgs(job, args, false)", "\t// Buffered, so the submit loop never blocks if this owner retires before", "\t// reading the result.", "\tjobW.ResultCh[0] = make(chan jobSubmitResult, 1)", "\tselect {", "\tcase r.executor.limitJobCh <- jobW:", "\tcase <-ctx.Done():", "\t\treturn ctx.Err()", "\t}", "\tselect {", "\tcase result := <-jobW.ResultCh[0]:", "\t\t// Nobody waits for this job to finish.", "\t\tr.executor.delJobDoneCh(result.jobID)", "\t\tif result.err != nil {", "\t\t\treturn errors.Trace(result.err)", "\t\t}", "\t\tlogutil.DDLLogger().Info(\"storage class interval recalculation submitted\",", "\t\t\tzap.Int64(\"jobID\", result.jobID), zap.Int64(\"tableID\", tblInfo.ID),", "\t\t\tzap.String(\"table\", fmt.Sprintf(\"%s.%s\", dbInfo.Name.O, tblInfo.Name.O)), zap.Strings(\"toIA\", toIA))", "\t\treturn nil", "\tcase <-ctx.Done():", "\t\treturn ctx.Err()", "\t}", "}"], "pkg/ddl/engine_attribute.go": ["// Copyright 2025 PingCAP, Inc.", "//", "// Licensed under the Apache License, Version 2.0 (the \"License\");", "// you may not use this file except in compliance with the License.", "// You may obtain a copy of the License at", "//", "//     http://www.apache.org/licenses/LICENSE-2.0", "//", "// Unless required by applicable law or agreed to in writing, software", "// distributed under the License is distributed on an \"AS IS\" BASIS,", "// WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.", "// See the License for the specific language governing permissions and", "// limitations under the License.", "", "package ddl", "", "import (", "\t\"context\"", "\t\"encoding/json\"", "\t\"fmt\"", "", "\t\"github.com/pingcap/errors\"", "\t\"github.com/pingcap/tidb/pkg/config\"", "\t\"github.com/pingcap/tidb/pkg/config/kerneltype\"", "\tsess \"github.com/pingcap/tidb/pkg/ddl/session\"", "\t\"github.com/pingcap/tidb/pkg/infoschema\"", "\t\"github.com/pingcap/tidb/pkg/kv\"", "\t\"github.com/pingcap/tidb/pkg/meta/model\"", "\t\"github.com/pingcap/tidb/pkg/parser/ast\"", "\t\"github.com/pingcap/tidb/pkg/sessionctx\"", "\t\"github.com/pingcap/tidb/pkg/util/dbterror\"", "\t\"github.com/pingcap/tidb/pkg/util/logutil\"", "\t\"go.uber.org/zap\"", ")", "", "// checkStorageClassAdmission gates new SQL requests, not metadata parsing or", "// execution of already accepted jobs. CREATE checks built metadata to cover LIKE;", "// ALTER checks only its requested attribute so unrelated changes remain available.", "func checkStorageClassAdmission(engineAttribute string, tbInfo *model.TableInfo) error {", "\tif config.GetGlobalConfig().EnableStorageClass {", "\t\treturn nil", "\t}", "\thasStorageClass := false", "\tif engineAttribute != \"\" {", "\t\tattr, err := model.ParseEngineAttributeFromString(engineAttribute)", "\t\tif err != nil {", "\t\t\treturn dbterror.ErrEngineAttributeInvalidFormat.GenWithStackByArgs(fmt.Sprintf(\"'%v'\", err))", "\t\t}", "\t\thasStorageClass = attr.StorageClass != nil", "\t}", "\tif tbInfo != nil {", "\t\thasStorageClass = hasStorageClass || tbInfo.StorageClassTier != \"\" || len(tbInfo.StorageClassTransitions) > 0", "\t\tif tbInfo.Partition != nil {", "\t\t\tfor _, part := range tbInfo.Partition.Definitions {", "\t\t\t\thasStorageClass = hasStorageClass || part.StorageClassTier != \"\" || len(part.StorageClassTransitions) > 0", "\t\t\t}", "\t\t}", "\t}", "\tif hasStorageClass {", "\t\treturn dbterror.ErrGeneralUnsupportedDDL.GenWithStack(\"Storage class is disabled; set enable-storage-class = true in the TiDB configuration\")", "\t}", "\treturn nil", "}", "", "func handleEngineAttributeForCreateTable(input string, tbInfo *model.TableInfo) error {", "\tattr, err := model.ParseEngineAttributeFromString(input)", "\tif err != nil {", "\t\treturn dbterror.ErrEngineAttributeInvalidFormat.GenWithStackByArgs(fmt.Sprintf(\"'%v'\", err))", "\t}", "", "\t// Keep the original string for SHOW CREATE TABLE.", "\ttbInfo.EngineAttribute = input", "", "\tif attr.StorageClass != nil {", "\t\tsettings, err := BuildStorageClassSettingsFromJSON(attr.StorageClass)", "\t\tif err != nil {", "\t\t\treturn errors.Trace(err)", "\t\t}", "", "\t\tlogutil.BgLogger().Info(\"storage class: create table with settings\",", "\t\t\tzap.Int64(\"tableID\", tbInfo.ID), zap.Any(\"settings\", settings))", "", "\t\tif err = BuildStorageClassForTable(tbInfo, settings); err != nil {", "\t\t\treturn errors.Trace(err)", "\t\t}", "\t}", "", "\t// Handle other fields in the future.", "", "\treturn nil", "}", "", "func getStorageClassSettingsFromTableInfo(tbInfo *model.TableInfo) (*model.StorageClassSettings, error) {", "\tattr, err := model.ParseEngineAttributeFromString(tbInfo.EngineAttribute)", "\tif err != nil {", "\t\treturn nil, dbterror.ErrEngineAttributeInvalidFormat.GenWithStackByArgs(fmt.Sprintf(\"'%v'\", err))", "\t}", "", "\tif attr.StorageClass == nil {", "\t\treturn nil, nil", "\t}", "", "\tsettings, err := BuildStorageClassSettingsFromJSON(attr.StorageClass)", "\tif err != nil {", "\t\treturn nil, errors.Trace(err)", "\t}", "", "\tlogutil.BgLogger().Info(\"storage class: get settings from table info\",", "\t\tzap.Int64(\"tableID\", tbInfo.ID), zap.Any(\"settings\", settings))", "\treturn settings, nil", "}", "", "func rebuildStorageClassForPartitions(tbInfo *model.TableInfo, partitions []model.PartitionDefinition) error {", "\tsettings, err := getStorageClassSettingsFromTableInfo(tbInfo)", "\tif err != nil || settings == nil {", "\t\treturn errors.Trace(err)", "\t}", "\treturn BuildStorageClassForPartitions(partitions, tbInfo, settings)", "}", "", "func (w *worker) onModifyTableEngineAttribute(jobCtx *jobContext, job *model.Job) (ver int64, _ error) {", "\targs, err := model.GetModifyTableEngineAttributeArgs(job)", "\tif err != nil {", "\t\tjob.State = model.JobStateCancelled", "\t\treturn ver, errors.Trace(err)", "\t}", "", "\tattr, err := model.ParseEngineAttributeFromString(args.EngineAttribute)", "\tif err != nil {", "\t\tjob.State = model.JobStateCancelled", "\t\treturn ver, errors.Trace(err)", "\t}", "", "\ttblInfo, err := GetTableInfoAndCancelFaultJob(jobCtx.metaMut, job, job.SchemaID)", "\tif err != nil {", "\t\treturn ver, errors.Trace(err)", "\t}", "", "\tif args.IntervalRecalculation && tblInfo.EngineAttribute != args.EngineAttribute {", "\t\tlogutil.BgLogger().Info(\"storage class interval recalculation skipped, engine attribute changed\",", "\t\t\tzap.Int64(\"tableID\", tblInfo.ID), zap.String(\"table\", tblInfo.Name.O))", "\t\tjob.FinishTableJob(model.JobStateDone, model.StatePublic, ver, tblInfo)", "\t\treturn ver, nil", "\t}", "", "\tif job.MultiSchemaInfo != nil && job.MultiSchemaInfo.Revertible {", "\t\tjob.MarkNonRevertible()", "\t\treturn ver, nil", "\t}", "\toldState := snapshotPhysicalStorageClasses(tblInfo)", "", "\tnewTblInfo := tblInfo", "\tif args.IntervalRecalculation {", "\t\t// Evaluate on a copy so the checked result is exactly what is applied.", "\t\tnewTblInfo = tblInfo.Clone()", "\t}", "\t// Keep the original string for SHOW CREATE TABLE.", "\tnewTblInfo.EngineAttribute = args.EngineAttribute", "", "\tif err := onAlterTableStorageClassSettings(attr.StorageClass, newTblInfo); err != nil {", "\t\tjob.State = model.JobStateCancelled", "\t\treturn ver, errors.Trace(err)", "\t}", "\tif args.IntervalRecalculation && !shouldApplyStorageClassIntervalRecalculation(newTblInfo, oldState, snapshotPhysicalStorageClasses(newTblInfo)) {", "\t\tjob.FinishTableJob(model.JobStateDone, model.StatePublic, ver, tblInfo)", "\t\treturn ver, nil", "\t}", "\ttblInfo = newTblInfo", "\tver, err = updateVersionAndTableInfo(jobCtx, job, tblInfo, true)", "\tif err != nil {", "\t\treturn ver, errors.Trace(err)", "\t}", "\tif attr.StorageClass != nil && kerneltype.IsNextGen() {", "\t\tpending, err := prepareExplicitStorageClassTransition(jobCtx, job, tblInfo, oldState)", "\t\tif err != nil {", "\t\t\treturn ver, errors.Trace(err)", "\t\t}", "\t\tpending.schemaVersion = ver", "\t\tif pending.schemaVersion == 0 && job.MultiSchemaInfo != nil && job.MultiSchemaInfo.SkipVersion {", "\t\t\tpending.schemaVersion = jobCtx.sharedMultiSchemaVersion", "\t\t}", "\t\tif pending.schemaVersion <= 0 {", "\t\t\treturn ver, errors.New(\"storage class transition schema version is unavailable\")", "\t\t}", "\t\tif jobCtx.deferStorageClassTransitionStaging {", "\t\t\tjobCtx.pendingStorageClassTransitions = append(jobCtx.pendingStorageClassTransitions, pending)", "\t\t} else if err := pending.stage(jobCtx.stepCtx, w.sess, jobCtx.storageClassTransitionManager); err != nil {", "\t\t\treturn ver, errors.Trace(err)", "\t\t}", "\t}", "\tjob.FinishTableJob(model.JobStateDone, model.StatePublic, ver, tblInfo)", "\treturn ver, nil", "}", "", "// storageClassTransitionStagingError marks failures that require rolling back", "// history SQL and the metadata changes released by its preceding statements.", "type storageClassTransitionStagingError struct {", "\tcause error", "}", "", "func (e *storageClassTransitionStagingError) Error() string {", "\treturn e.cause.Error()", "}", "", "func (e *storageClassTransitionStagingError) Unwrap() error {", "\treturn e.cause", "}", "", "func (e *storageClassTransitionStagingError) Cause() error {", "\treturn e.cause", "}", "", "// checkpointStorageClassTransitionStep captures the whole outer DDL step, since", "// a multi-schema batch can change metadata before it stages transition history.", "// Other DDL jobs retain their existing statement rollback behavior.", "func checkpointStorageClassTransitionStep(se *sess.Session, txn kv.Transaction, job *model.Job) func() {", "\tif !kerneltype.IsNextGen() {", "\t\treturn nil", "\t}", "\tstagesHistory := job.Type == model.ActionModifyEngineAttribute", "\tif job.Type == model.ActionMultiSchemaChange && job.MultiSchemaInfo != nil {", "\t\tfor _, sub := range job.MultiSchemaInfo.SubJobs {", "\t\t\tif sub.Type == model.ActionModifyEngineAttribute {", "\t\t\t\tstagesHistory = true", "\t\t\t\tbreak", "\t\t\t}", "\t\t}", "\t}", "\tif !stagesHistory {", "\t\treturn nil", "\t}", "", "\tcheckpoint := txn.GetMemDBCheckpoint()", "\ttxnCtx := se.GetSessionVars().TxnCtx", "\ttxnCtxSavepoint := txnCtx.GetCurrentSavepoint()", "\tbinlogInfo := job.BinlogInfo", "\tif binlogInfo != nil {", "\t\tsaved := *binlogInfo", "\t\tbinlogInfo = &saved", "\t}", "\tresumeReason := job.ResumeReason", "\tvar subJobs []model.SubJob", "\tif job.MultiSchemaInfo != nil {", "\t\tsubJobs = make([]model.SubJob, len(job.MultiSchemaInfo.SubJobs))", "\t\tfor i, sub := range job.MultiSchemaInfo.SubJobs {", "\t\t\tsubJobs[i] = *sub.Clone()", "\t\t}", "\t}", "", "\treturn func() {", "\t\ttxnCtx.RestoreBySavepoint(txnCtxSavepoint)", "\t\ttxn.RollbackMemDBToCheckpoint(checkpoint)", "\t\tjob.BinlogInfo = binlogInfo", "\t\tjob.ResumeReason = resumeReason", "\t\tjob.LastSchemaVersion = 0", "\t\tfor i := range subJobs {", "\t\t\tjob.MultiSchemaInfo.SubJobs[i] = &subJobs[i]", "\t\t}", "\t\t// Keep error accounting, the cancellation decision, and durable choices", "\t\t// such as ReorgMeta.UseCloudStorage made while executing the step.", "\t}", "}", "", "type pendingStorageClassTransition struct {", "\ttblInfo       *model.TableInfo", "\told           map[int64]physicalStorageClass", "\tschemaVersion int64", "\tstartTS       uint64", "\tschemaName    string", "\ttableName     string", "}", "", "func prepareExplicitStorageClassTransition(", "\tjobCtx *jobContext,", "\tjob *model.Job,", "\ttblInfo *model.TableInfo,", "\told map[int64]physicalStorageClass,", ") (pendingStorageClassTransition, error) {", "\tstartTS := job.RealStartTS", "\tif startTS == 0 {", "\t\tstartTS = job.StartTS", "\t}", "\tif startTS == 0 {", "\t\tstartTS = jobCtx.metaMut.StartTS", "\t}", "\tif startTS == 0 {", "\t\treturn pendingStorageClassTransition{}, errors.New(\"storage class transition start TSO is unavailable\")", "\t}", "\tdbInfo, err := jobCtx.metaMut.GetDatabase(job.SchemaID)", "\tif err != nil {", "\t\treturn pendingStorageClassTransition{}, errors.Trace(err)", "\t}", "\treturn pendingStorageClassTransition{", "\t\ttblInfo:    tblInfo.Clone(),", "\t\told:        old,", "\t\tstartTS:    startTS,", "\t\tschemaName: dbInfo.Name.O,", "\t\ttableName:  tblInfo.Name.O,", "\t}, nil", "}", "", "func (pending pendingStorageClassTransition) stage(", "\tctx context.Context,", "\tse *sess.Session,", "\tmanager *storageClassTransitionManager,", ") error {", "\terr := stageStorageClassTransitions(", "\t\tctx,", "\t\tse,", "\t\tmanager,", "\t\tpending.tblInfo,", "\t\tpending.old,", "\t\tpending.schemaVersion,", "\t\tpending.startTS,", "\t\tpending.schemaName,", "\t\tpending.tableName,", "\t)", "\tif err != nil {", "\t\treturn &storageClassTransitionStagingError{cause: err}", "\t}", "\treturn nil", "}", "", "func (w *worker) flushPendingStorageClassTransitions(jobCtx *jobContext) error {", "\tfor _, pending := range jobCtx.pendingStorageClassTransitions {", "\t\tif err := pending.stage(jobCtx.stepCtx, w.sess, jobCtx.storageClassTransitionManager); err != nil {", "\t\t\treturn errors.Trace(err)", "\t\t}", "\t}", "\tjobCtx.pendingStorageClassTransitions = nil", "\treturn nil", "}", "", "func onAlterTableStorageClassSettings(storageClass json.RawMessage, tblInfo *model.TableInfo) error {", "\tif storageClass == nil {", "\t\treturn nil", "\t}", "", "\tsettings, err := BuildStorageClassSettingsFromJSON(storageClass)", "\tif err != nil {", "\t\treturn errors.Trace(err)", "\t}", "", "\tlogutil.BgLogger().Info(\"storage class: alter table settings\",", "\t\tzap.Int64(\"tableID\", tblInfo.ID), zap.Any(\"settings\", settings))", "", "\tif err = BuildStorageClassForTable(tblInfo, settings); err != nil {", "\t\treturn errors.Trace(err)", "\t}", "\tif tblInfo.Partition != nil && len(tblInfo.Partition.Definitions) > 0 {", "\t\tif err = BuildStorageClassForPartitions(tblInfo.Partition.Definitions, tblInfo, settings); err != nil {", "\t\t\treturn errors.Trace(err)", "\t\t}", "\t}", "", "\treturn nil", "}", "", "// AlterTableEngineAttribute updates the table engine attribute.", "func (e *executor) AlterTableEngineAttribute(ctx sessionctx.Context, ident ast.Ident, engineAttribute string) error {", "\tis := e.infoCache.GetLatest()", "\tschema, ok := is.SchemaByName(ident.Schema)", "\tif !ok {", "\t\treturn infoschema.ErrDatabaseNotExists.GenWithStackByArgs(ident.Schema)", "\t}", "", "\ttb, err := is.TableByName(e.ctx, ident.Schema, ident.Name)", "\tif err != nil {", "\t\treturn errors.Trace(infoschema.ErrTableNotExists.GenWithStackByArgs(ident.Schema, ident.Name))", "\t}", "\tif _, err = model.ParseEngineAttributeFromString(engineAttribute); err != nil {", "\t\treturn dbterror.ErrEngineAttributeInvalidFormat.GenWithStackByArgs(fmt.Sprintf(\"'%v'\", err))", "\t}", "\tif err = checkStorageClassIntervalPartitionKey(engineAttribute, tb.Meta()); err != nil {", "\t\treturn err", "\t}", "", "\tjob := &model.Job{", "\t\tVersion:        model.GetJobVerInUse(),", "\t\tSchemaID:       schema.ID,", "\t\tTableID:        tb.Meta().ID,", "\t\tSchemaName:     schema.Name.L,", "\t\tTableName:      tb.Meta().Name.L,", "\t\tType:           model.ActionModifyEngineAttribute,", "\t\tBinlogInfo:     &model.HistoryInfo{},", "\t\tCDCWriteSource: ctx.GetSessionVars().CDCWriteSource,", "\t\tSQLMode:        ctx.GetSessionVars().SQLMode,", "\t}", "\targs := &model.ModifyTableEngineAttributeArgs{", "\t\tEngineAttribute: engineAttribute,", "\t}", "\terr = e.doDDLJob2(ctx, job, args)", "\treturn errors.Trace(err)", "}"]};
